  class << self
    alias bs2093_describe describe
    def describe(object)
      return 'Без вычета ЗАЩ; Guard 100%' if object.is_a?(RPG::Skill) && object.id==100
      if object.is_a?(RPG::Weapon) && WEAPONS093[object.id];return WEAPONS093[object.id][0];end
      value=object.is_a?(RPG::Skill) ? SKILLS093[object.id] : object.is_a?(RPG::Item) ? ITEMS093[object.id] : nil
      value || bs2093_describe(object)
    end
    def describe_final(object)
      object.is_a?(RPG::Weapon) && WEAPONS093[object.id] ? WEAPONS093[object.id][1] : describe(object)
    end
    def for_row(row,prefix)
      obj=row[:object];return '' unless obj
      text=enabled?(prefix) ? describe(obj).to_s : ''
      actor=SceneManager.scene.is_a?(Scene_Battle) ? BattleManager.actor : nil
      if prefix=='N' && actor && BS2Suite::DirectWeapons.selected(actor)==obj
        text=enabled?(prefix) ? describe_final(obj).to_s : ''
        text+=' · [последнее действие]'
      elsif actor && BS2Suite::BattleSupport.configured?(actor,obj)
        text+=' · [поддержка'+(BS2Suite::BattleSupport.active? ? '' : ': пауза')+']'
      end
      text
    end
  end
end
module BS2Suite
  class PaletteWindow
    def line_height
      @group && !@assignment && ShortNotes.enabled?(@prefix) ? 58 : 26
    end
    def visible_line_number
      limit=[(Graphics.height-88)/line_height,1].max
      [[item_max,10,limit].min,1].max
    end
    alias bs2093_note_list make_command_list
    def make_command_list
      bs2093_note_list
      return unless @group && !@assignment && @transition.empty?
      @list.each do |entry|
        row=entry[:ext];next unless row && row[:object]
        obj=row[:object];suffix=''
        if obj.is_a?(RPG::Item);suffix=' ×'+$game_party.item_number(obj).to_s
        elsif obj.is_a?(RPG::Skill)
          view=row[:source].is_a?(RPG::Weapon) ? Projection.weapon(@actor,row[:source]) : @actor
          suffix=' · '+view.skill_mp_cost(obj).to_s+' MP'
        end
        entry[:name]=row[:digit].to_s+'  '+obj.name+suffix
      end
    end
    def draw_item(index)
      row=@list[index] && @list[index][:ext]
      return super unless @group && !@assignment && row && row[:object] && @transition.empty?
      rect=item_rect_for_text(index);change_color(normal_color,command_enabled?(index))
      contents.font.size=18
      note=ShortNotes.for_row(row,@prefix).sub(/ · \[последнее действие\]\z/,'')
      first=@list[index][:name]
      first+=' [последнее]' if @prefix=='N' && DirectWeapons.selected(@actor)==row[:object]
      first+=' [авто]' if @prefix!='N' && BattleSupport.configured?(@actor,row[:object])
      draw_text(rect.x,rect.y,rect.width,22,BS2Modules.fit(self,first,rect.width))
      if line_height>26
        contents.font.size=14
        words=note.split(/\s+/);parts=['']
        words.each do |word|
          value=parts[-1].empty? ? word : parts[-1]+' '+word
          if text_size(value).width>rect.width && !parts[-1].empty?;parts<<word
          else;parts[-1]=value;end
        end
        if parts.size>2
          contents.font.size=12;parts=['']
          words.each do |word|
            value=parts[-1].empty? ? word : parts[-1]+' '+word
            text_size(value).width>rect.width && !parts[-1].empty? ? parts<<word : parts[-1]=value
          end
        end
        parts.each_with_index { |line,i| draw_text(rect.x,rect.y+22+i*16,rect.width,16,line) }
      end
      contents.font.size=Font.default_size
    end
  end
end
